<?php
/**  Form Builder - Admin UI (hooks the admin hook, as every enabled plugin must). */
if (empty($GLOBALS['adminarea'])) return;
add_menu_item('dashboard', ['name'=>'nexa-forms','class'=>(($_GET['plugin_page']??'')==='nexa-forms')?'active':'','icon'=>'fa fa-wpforms fa-fw','label'=>' Form Builder','link'=>'admin.php?plugin_page=nexa-forms'], 52);
add_action('nexa_admin','nexa_forms_admin_render'); add_action('di_admin','nexa_forms_admin_render'); add_action('up_admin','nexa_forms_admin_render');
function nexa_forms_admin_render(): void { static $done=false; if($done) return; if(($_GET['plugin_page']??'')!=='nexa-forms') return; $done=true;
    nexa_forms_ensure();
    if(($_SERVER['REQUEST_METHOD']??'')==='POST' && nexa_verify_csrf()){ if(($_POST['do']??'')==='del_sub') query("DELETE FROM nexa_form_subs WHERE id=?",[(int)$_POST['id']]); elseif(($_POST['do']??'')==='del_form') query("DELETE FROM nexa_forms WHERE id=?",[(int)$_POST['id']]); else query("INSERT INTO nexa_forms (name,fields,recipient,success_msg,created_at) VALUES (?,?,?,?,?)",[trim((string)$_POST['name']),trim((string)$_POST['fields']),trim((string)$_POST['recipient']),trim((string)$_POST['success_msg']),date('Y-m-d H:i:s')]); echo '<div class="alert alert-success">Forms updated.</div>'; }
    echo '<h2><i class="fa fa-wpforms"></i> Form Builder</h2><form method="post" class="form-inline">'.nexa_csrf_field().'<input name="name" required class="form-control" placeholder="Form name"> <input name="fields" required class="form-control" placeholder="Fields: Name, Email, Message" style="min-width:260px"> <input name="recipient" class="form-control" placeholder="Notify email"> <input name="success_msg" class="form-control" placeholder="Success message"> <button class="btn btn-primary">Create Form</button></form><hr>';
    foreach(query("SELECT * FROM nexa_forms ORDER BY id DESC") as $f){ echo '<div class="panel panel-default"><div class="panel-heading"><strong>'.esc_html($f['name']).'</strong> - embed: <code>[nexa_form id="'.(int)$f['id'].'"]</code> <form method="post" style="display:inline;float:right">'.nexa_csrf_field().'<input type="hidden" name="id" value="'.(int)$f['id'].'"><button name="do" value="del_form" class="btn btn-xs btn-danger">Delete form</button></form></div><div class="panel-body">'; $subs=query("SELECT * FROM nexa_form_subs WHERE form_id=? ORDER BY id DESC LIMIT 20",[(int)$f['id']]); if(empty($subs)) echo '<p class="text-muted">No submissions yet.</p>'; foreach($subs as $sub){ echo '<div style="border-bottom:1px solid #eee;padding:6px 0"><small>'.esc_html($sub['created_at']).' - '.esc_html($sub['ip']).'</small><br>'; $d=maybe_unserialize($sub['data']); if(is_array($d)) foreach($d as $k=>$v) echo '<strong>'.esc_html($k).':</strong> '.esc_html((string)$v).' '; echo '<form method="post" style="display:inline">'.nexa_csrf_field().'<input type="hidden" name="id" value="'.(int)$sub['id'].'"><button name="do" value="del_sub" class="btn btn-xs btn-default">Delete</button></form></div>'; } echo '</div></div>'; }
    echo '<p class="text-muted">Tip: for a simple contact form, the built-in <code>[contact_form]</code> (Nexa Contact) may be all you need.</p>'; }

